fs={"tanh":lambda x:np.tanh(x),"1-exp":lambda x:1-np.exp(-x),"erf":lambda x:erf(x),
    "x/sqrt(1+x2)":lambda x:x/np.sqrt(1+x**2),"1-exp(-x2)":lambda x:1-np.exp(-x**2),"x/(1+x)":lambda x:x/(1+x),"log1p":lambda x:np.log1p(x)}
for name,f in fs.items():
    def fun(p):
        T=f(p[0]*t)
        return np.column_stack([T,T*P,T*P**2,T*P**3,P,P**2,P**3,P*t,P**2*t,t,one])
    def resid(p):
        X=fun(p); c,_,_,_=np.linalg.lstsq(X,dP_dt,rcond=None); return dP_dt-X@c
    best=None
